INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('30817fa0-f95f-567c-bb09-bcbfd3eb6aa1', 'Ecuador SMV Sustainability and Corporate Governance Guidelines', 'SMV Sustainability and Corporate Governance Guidelines', 'The COFIDE Corporate Sustainability Report outlines the sustainability policies, environmental impact management, and corporate governance practices of Corporación Financiera de Desarrollo S.A. (COFIDE), a financial institution in Ecuador. The report details COFIDE’s approach to environmental sustainability, including greenhouse gas (GHG) emissions measurement, water and energy consumption, solid waste management, and compliance with national and international environmental standards. The company follows an Integrated Management System to track and mitigate environmental risks. It has also established a three-year Eco-Efficiency Plan (2019-2021) with targets for reducing energy and water consumption, minimizing waste, and lowering its carbon footprint. The report highlights social and labor policies, including human rights protections, labor rights compliance, gender equality, and employee well-being. COFIDE aligns its sustainability efforts with global frameworks such as ISO 26000, the Sustainable Development Goals (SDGs), and Global Reporting Initiative (GRI) standards.', 'The COFIDE Corporate Sustainability Report outlines the sustainability policies, environmental impact management, and corporate governance practices of Corporación Financiera de Desarrollo S.A. (COFIDE), a financial institution in Ecuador. The report details COFIDE’s approach to environmental sustainability, including greenhouse gas (GHG) emissions measurement, water and energy consumption, solid waste management, and compliance with national and international environmental standards. The company follows an Integrated Management System to track and mitigate environmental risks. It has also established a three-year Eco-Efficiency Plan (2019-2021) with targets for reducing energy and water consumption, minimizing waste, and lowering its carbon footprint. The report highlights social and labor policies, including human rights protections, labor rights compliance, gender equality, and employee well-being. COFIDE aligns its sustainability efforts with global frameworks such as ISO 26000, the Sustainable Development Goals (SDGs), and Global Reporting Initiative (GRI) standards.', 'The COFIDE Corporate Sustainability Report outlines the sustainability policies, environmental impact management, and corporate governance practices of Corporación Financiera de Desarrollo S.A. (COFIDE), a financial institution in Ecuador. The report details COFIDE’s approach to environmental sustainability, including greenhouse gas (GHG) emissions measurement, water and energy consumption, solid waste management, and compliance with national and international environmental standards. The company follows an Integrated Management System to track and mitigate environmental risks. It has also established a three-year Eco-Efficiency Plan (2019-2021) with targets for reducing energy and water consumption, minimizing waste, and lowering its carbon footprint. The report highlights social and labor policies, including human rights protections, labor rights compliance, gender equality, and employee well-being. COFIDE aligns its sustainability efforts with global frameworks such as ISO 26000, the Sustainable Development Goals (SDGs), and Global Reporting Initiative (GRI) standards.', 'Ecuador', 'climate', 'in_force', '2020-01-01'::date, 'Ecuador', 'https://www.carrotsandsticks.org/policies/47_3', ARRAY['guidance_frameworks', 'sdg13', 'sdg8', 'sdg7', 'sdg5', 'sdg16', 'sdg12', 'ecuador', 'voluntary']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('f6d26e3a-5112-52ca-82b5-65d695f26bd8', 'Environmental Code of Ecuador (Código Ambiental del Ecuador)', 'Environmental Code of Ecuador (Código Ambiental del Ecuador)', 'The Código Orgánico del Ambiente (COA) is the main environmental legal framework in Ecuador, regulating environmental rights, conservation, sustainable use of natural resources, pollution control, and climate change mitigation. It establishes guidelines for public and private entities, ensuring compliance with environmental regulations while promoting sustainable development. The COA enforces the "Rights of Nature" principle, recognizing nature as a legal entity with rights. It sets responsibilities for businesses in environmental management, requiring them to conduct environmental impact assessments, adopt mitigation measures, and comply with emissions limits. The law also introduces mechanisms for environmental education, citizen participation, and government accountability in environmental governance. Furthermore, it outlines economic incentives and penalties for compliance or non-compliance with environmental standards.', 'The Código Orgánico del Ambiente (COA) is the main environmental legal framework in Ecuador, regulating environmental rights, conservation, sustainable use of natural resources, pollution control, and climate change mitigation. It establishes guidelines for public and private entities, ensuring compliance with environmental regulations while promoting sustainable development. The COA enforces the "Rights of Nature" principle, recognizing nature as a legal entity with rights. It sets responsibilities for businesses in environmental management, requiring them to conduct environmental impact assessments, adopt mitigation measures, and comply with emissions limits. The law also introduces mechanisms for environmental education, citizen participation, and government accountability in environmental governance. Furthermore, it outlines economic incentives and penalties for compliance or non-compliance with environmental standards.', 'The Código Orgánico del Ambiente (COA) is the main environmental legal framework in Ecuador, regulating environmental rights, conservation, sustainable use of natural resources, pollution control, and climate change mitigation. It establishes guidelines for public and private entities, ensuring compliance with environmental regulations while promoting sustainable development. The COA enforces the "Rights of Nature" principle, recognizing nature as a legal entity with rights. It sets responsibilities for businesses in environmental management, requiring them to conduct environmental impact assessments, adopt mitigation measures, and comply with emissions limits. The law also introduces mechanisms for environmental education, citizen participation, and government accountability in environmental governance. Furthermore, it outlines economic incentives and penalties for compliance or non-compliance with environmental standards.', 'Ecuador', 'climate', 'in_force', '2017-01-01'::date, 'Ecuador', 'https://www.carrotsandsticks.org/policies/47_1', ARRAY['sdg4', 'sdg13', 'other sustainability policy', 'regulations', 'sdg7', 'mandatory', 'sdg16', 'ecuador', 'sdg15', 'sdg3']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('f6c62b74-5329-501a-8085-522588a9ac6e', 'Ecuador Guide to Good Environmental Practices', 'Guide to Good Environmental Practices', 'This guide contains a series of behavioral guidelines in relation to the significant environmental aspects that have been identified in the administrative units, that is, those elements of the entity''s activities, products or services that interact with the environment, producing an associated impact.', 'This guide contains a series of behavioral guidelines in relation to the significant environmental aspects that have been identified in the administrative units, that is, those elements of the entity''s activities, products or services that interact with the environment, producing an associated impact.', 'This guide contains a series of behavioral guidelines in relation to the significant environmental aspects that have been identified in the administrative units, that is, those elements of the entity''s activities, products or services that interact with the environment, producing an associated impact.', 'Ecuador', 'climate', 'in_force', '2017-01-01'::date, 'Ecuador', 'https://www.carrotsandsticks.org/policies/47_11', ARRAY['other sustainability policy', 'regulations', 'sdg7', 'mandatory', 'sdg12', 'ecuador']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('5cef2f2f-8aa7-5030-b3f6-a5d803c1b4b9', 'Ecuador Organic Law of Human Mobility', 'Organic Law of Human Mobility', 'The purpose of this Law is to regulate the exercise of rights, obligations, institutions and mechanisms related to people in human mobility, which includes emigrants, immigrants, people in transit, returned Ecuadorians, those who require international protection, victims of crimes of human trafficking and migrant smuggling. In the case of victims of human trafficking and migrant smuggling, this Law aims to establish the framework for prevention, protection, care and reintegration that the State will develop through the different public policies, in accordance with the legal system.', 'The purpose of this Law is to regulate the exercise of rights, obligations, institutions and mechanisms related to people in human mobility, which includes emigrants, immigrants, people in transit, returned Ecuadorians, those who require international protection, victims of crimes of human trafficking and migrant smuggling. In the case of victims of human trafficking and migrant smuggling, this Law aims to establish the framework for prevention, protection, care and reintegration that the State will develop through the different public policies, in accordance with the legal system.', 'The purpose of this Law is to regulate the exercise of rights, obligations, institutions and mechanisms related to people in human mobility, which includes emigrants, immigrants, people in transit, returned Ecuadorians, those who require international protection, victims of crimes of human trafficking and migrant smuggling. In the case of victims of human trafficking and migrant smuggling, this Law aims to establish the framework for prevention, protection, care and reintegration that the State will develop through the different public policies, in accordance with the legal system.', 'Ecuador', 'governance', 'in_force', '2017-01-01'::date, 'Ecuador', 'https://www.carrotsandsticks.org/policies/47_13', ARRAY['ecuador', 'mandatory', 'other sustainability policy', 'regulations']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('db879ba0-cec5-55a0-bc25-cf2e4b34b5f0', 'Ecuador MDT-2015-0233 agreement issuing the rules governing special labor', 'MDT-2015-0233 agreement issuing the rules governing special labor relationships in the agricultural sector', 'The "Acuerdo MDT-2015-0233" establishes the rules and obligations related to special employment relationships in the agricultural sector in Ecuador. The agreement aims to ensure that workers in the sector are provided with adequate working conditions, fair wages, and other benefits, such as social security and health insurance. The agreement also requires employers to provide a safe and healthy work environment, to comply with labor laws and regulations, and to keep accurate records of their workers. Employers are also obligated to provide training to their employees to improve their skills and productivity.', 'The "Acuerdo MDT-2015-0233" establishes the rules and obligations related to special employment relationships in the agricultural sector in Ecuador. The agreement aims to ensure that workers in the sector are provided with adequate working conditions, fair wages, and other benefits, such as social security and health insurance. The agreement also requires employers to provide a safe and healthy work environment, to comply with labor laws and regulations, and to keep accurate records of their workers. Employers are also obligated to provide training to their employees to improve their skills and productivity.', 'The "Acuerdo MDT-2015-0233" establishes the rules and obligations related to special employment relationships in the agricultural sector in Ecuador. The agreement aims to ensure that workers in the sector are provided with adequate working conditions, fair wages, and other benefits, such as social security and health insurance. The agreement also requires employers to provide a safe and healthy work environment, to comply with labor laws and regulations, and to keep accurate records of their workers. Employers are also obligated to provide training to their employees to improve their skills and productivity.', 'Ecuador', 'nature', 'in_force', '2015-01-01'::date, 'Ecuador', 'https://www.carrotsandsticks.org/policies/47_5', ARRAY['sdg4', 'sdg2', 'sdg8', 'other sustainability policy', 'regulations', 'mandatory', 'ecuador', 'sdg3']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('f7b9f96b-97a1-5bc5-a5de-68c1aa43c763', 'National Climate Change Strategy of Ecuador', 'National Climate Change Strategy of Ecuador', 'This document will guide and dictate in an orderly and coordinated manner the actions and measures that Ecuador needs to promote to prepare the Nation to face the most intense and frequent extreme weather events; that will undoubtedly affect all sectors of the economy of our country. On the other hand, it will dictate the actions that Ecuador will proactively implement to reduce the level of greenhouse gas emissions in the strategic productive and social sectors to contribute to a global effort that seeks, with respect to its level of development and capabilities, stabilize emissions at a level that does not interfere with the climate system, allowing ecosystems to adapt naturally to an increase in the planet''s temperature.', 'This document will guide and dictate in an orderly and coordinated manner the actions and measures that Ecuador needs to promote to prepare the Nation to face the most intense and frequent extreme weather events; that will undoubtedly affect all sectors of the economy of our country. On the other hand, it will dictate the actions that Ecuador will proactively implement to reduce the level of greenhouse gas emissions in the strategic productive and social sectors to contribute to a global effort that seeks, with respect to its level of development and capabilities, stabilize emissions at a level that does not interfere with the climate system, allowing ecosystems to adapt naturally to an increase in the planet''s temperature.', 'This document will guide and dictate in an orderly and coordinated manner the actions and measures that Ecuador needs to promote to prepare the Nation to face the most intense and frequent extreme weather events; that will undoubtedly affect all sectors of the economy of our country. On the other hand, it will dictate the actions that Ecuador will proactively implement to reduce the level of greenhouse gas emissions in the strategic productive and social sectors to contribute to a global effort that seeks, with respect to its level of development and capabilities, stabilize emissions at a level that does not interfere with the climate system, allowing ecosystems to adapt naturally to an increase in the planet''s temperature.', 'Ecuador', 'climate', 'in_force', '2012-01-01'::date, 'Ecuador', 'https://www.carrotsandsticks.org/policies/47_18', ARRAY['sdg13', 'other sustainability policy', 'sdg11', 'mandatory', 'sdg6', 'mandatory_regulations', 'ecuador', 'sdg15', 'sdg3']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('e18d3a29-481b-55ce-9092-3a346f674d92', 'Central Bank of Egypt’s Sustainable Finance Binding Regulations', 'Central Bank of Egypt’s Sustainable Finance Binding Regulations', 'The Central Bank of Egypt has announced that it will issue binding regulations on sustainable finance in order to achieve sustainable development goals and Egypt''s Vision 2030. The regulations are based on a gap analysis conducted by the Central Bank of Egypt on sustainable finance practices in the Egyptian banking sector. The regulations require banks to incorporate sustainable finance policies within their credit and investment policies, establish an independent department for sustainability and sustainable finance, and prepare periodic reports on their sustainable financing activities. Banks must also consult an accredited environmental expert to assess environmental risks of large corporate projects. The regulations will take effect on various dates starting from April 1st 2023 and will be enforced by the Central Bank of Egypt.', 'The Central Bank of Egypt has announced that it will issue binding regulations on sustainable finance in order to achieve sustainable development goals and Egypt''s Vision 2030. The regulations are based on a gap analysis conducted by the Central Bank of Egypt on sustainable finance practices in the Egyptian banking sector. The regulations require banks to incorporate sustainable finance policies within their credit and investment policies, establish an independent department for sustainability and sustainable finance, and prepare periodic reports on their sustainable financing activities. Banks must also consult an accredited environmental expert to assess environmental risks of large corporate projects. The regulations will take effect on various dates starting from April 1st 2023 and will be enforced by the Central Bank of Egypt.', 'The Central Bank of Egypt has announced that it will issue binding regulations on sustainable finance in order to achieve sustainable development goals and Egypt''s Vision 2030. The regulations are based on a gap analysis conducted by the Central Bank of Egypt on sustainable finance practices in the Egyptian banking sector. The regulations require banks to incorporate sustainable finance policies within their credit and investment policies, establish an independent department for sustainability and sustainable finance, and prepare periodic reports on their sustainable financing activities. Banks must also consult an accredited environmental expert to assess environmental risks of large corporate projects. The regulations will take effect on various dates starting from April 1st 2023 and will be enforced by the Central Bank of Egypt.', 'Egypt', 'climate', 'in_force', '2022-01-01'::date, 'Egypt', 'https://www.carrotsandsticks.org/policies/48_9', ARRAY['sdg13', 'regulations', 'egypt', 'mandatory', 'sdg16', 'sdg12', 'disclosure']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('a22139b0-1f83-507b-b6c1-933a2d69f0e6', 'Egypt Law of 2017 Promulgating the Investment Law', 'Law No. 72 of 2017 Promulgating the Investment Law', 'The provisions of the annexed Law shall govern the investment within the Arab Republic of Egypt. The provisions of the Law shall apply to local and foreign investment, regardless of its size, and investment shall be placed in accordance with the provisions of this Law, either under the regime of the Inland Investment, Investment Zones, Technological Zones, or Free Zones.', 'The provisions of the annexed Law shall govern the investment within the Arab Republic of Egypt. The provisions of the Law shall apply to local and foreign investment, regardless of its size, and investment shall be placed in accordance with the provisions of this Law, either under the regime of the Inland Investment, Investment Zones, Technological Zones, or Free Zones.', 'The provisions of the annexed Law shall govern the investment within the Arab Republic of Egypt. The provisions of the Law shall apply to local and foreign investment, regardless of its size, and investment shall be placed in accordance with the provisions of this Law, either under the regime of the Inland Investment, Investment Zones, Technological Zones, or Free Zones.', 'Egypt', 'climate', 'in_force', '2017-01-01'::date, 'Egypt', 'https://www.carrotsandsticks.org/policies/48_6', ARRAY['sdg4', 'sdg2', 'regulations', 'sdg7', 'egypt', 'mandatory', 'sdg6', 'disclosure', 'sdg15', 'sdg3']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('e44f4eb2-9f36-5073-b08a-1c746140eda9', 'Egypt Model Guidance for Reporting on ESG Performance &', 'Model Guidance for Reporting on ESG Performance & SDGs, 2016', 'The guide is designed to help integrating environmental, social and governance (ESG) information into capital market reports. The recommendations in this guide are designed to assist listed companies in EGX in integrating environmental, social and governance (ESG) information into effective capital market communication. There are no formal obligations associated with this guide.', 'The guide is designed to help integrating environmental, social and governance (ESG) information into capital market reports. The recommendations in this guide are designed to assist listed companies in EGX in integrating environmental, social and governance (ESG) information into effective capital market communication. There are no formal obligations associated with this guide.', 'The guide is designed to help integrating environmental, social and governance (ESG) information into capital market reports. The recommendations in this guide are designed to assist listed companies in EGX in integrating environmental, social and governance (ESG) information into effective capital market communication. There are no formal obligations associated with this guide.', 'Egypt', 'climate', 'in_force', '2016-01-01'::date, 'Egypt', 'https://www.carrotsandsticks.org/policies/48_1', ARRAY['guidance_frameworks', 'egypt', 'mandatory', 'sdg16', 'disclosure']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('cb5905ee-ed56-512b-b2d6-f666477dac6f', 'Egyptian Corporate Governance Code', 'Egyptian Corporate Governance Code, 2016', 'This Corporate Governance Code of the Arab Republic of Egypt, drafted by the Egyptian Institute of Directors (EIoD), at the Egyptian Financial Supervisory Authority, is the first comprehensive and updated release since 2005. The Code serves as a guide for best practices in the fields of governance, transparency and prudent management, for all stakeholders of the company adopting the Code.', 'This Corporate Governance Code of the Arab Republic of Egypt, drafted by the Egyptian Institute of Directors (EIoD), at the Egyptian Financial Supervisory Authority, is the first comprehensive and updated release since 2005. The Code serves as a guide for best practices in the fields of governance, transparency and prudent management, for all stakeholders of the company adopting the Code.', 'This Corporate Governance Code of the Arab Republic of Egypt, drafted by the Egyptian Institute of Directors (EIoD), at the Egyptian Financial Supervisory Authority, is the first comprehensive and updated release since 2005. The Code serves as a guide for best practices in the fields of governance, transparency and prudent management, for all stakeholders of the company adopting the Code.', 'Egypt', 'governance', 'in_force', '2016-01-01'::date, 'Egypt', 'https://www.carrotsandsticks.org/policies/48_2', ARRAY['regulations', 'egypt', 'mandatory', 'sdg16', 'disclosure', 'sdg9']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('ed7c72d2-adf7-512d-ac1f-c9cddd34ec08', 'Egyptian Corporate Governance Code', 'Egyptian Corporate Governance Code', 'The Egyptian Corporate Governance Code, issued by the Egyptian Financial Supervisory Authority (EFSA) and drafted by the Egyptian Institute of Directors (EIoD), serves as a comprehensive framework for corporate governance within Egypt. It sets guidelines to ensure transparency, prudent management, and efficiency in governance practices, focusing on listed and unlisted companies, financial institutions, and state-owned enterprises. This updated version from 2016 reflects best practices in global governance while adapting to the local context. The code emphasizes the roles of shareholders, boards of directors, and committees, and it establishes policies for transparency, disclosure, and internal controls. It also includes the "Comply or Explain" rule, where companies must comply with the Code’s principles or explain any deviations. The document highlights the importance of corporate social responsibility, whistleblowing policies, and succession planning as critical to effective governance. It seeks to guide companies towards improved sustainability, operational efficiency, and a stronger corporate culture aligned with international standards.', 'The Egyptian Corporate Governance Code, issued by the Egyptian Financial Supervisory Authority (EFSA) and drafted by the Egyptian Institute of Directors (EIoD), serves as a comprehensive framework for corporate governance within Egypt. It sets guidelines to ensure transparency, prudent management, and efficiency in governance practices, focusing on listed and unlisted companies, financial institutions, and state-owned enterprises. This updated version from 2016 reflects best practices in global governance while adapting to the local context. The code emphasizes the roles of shareholders, boards of directors, and committees, and it establishes policies for transparency, disclosure, and internal controls. It also includes the "Comply or Explain" rule, where companies must comply with the Code’s principles or explain any deviations. The document highlights the importance of corporate social responsibility, whistleblowing policies, and succession planning as critical to effective governance. It seeks to guide companies towards improved sustainability, operational efficiency, and a stronger corporate culture aligned with international standards.', 'The Egyptian Corporate Governance Code, issued by the Egyptian Financial Supervisory Authority (EFSA) and drafted by the Egyptian Institute of Directors (EIoD), serves as a comprehensive framework for corporate governance within Egypt. It sets guidelines to ensure transparency, prudent management, and efficiency in governance practices, focusing on listed and unlisted companies, financial institutions, and state-owned enterprises. This updated version from 2016 reflects best practices in global governance while adapting to the local context. The code emphasizes the roles of shareholders, boards of directors, and committees, and it establishes policies for transparency, disclosure, and internal controls. It also includes the "Comply or Explain" rule, where companies must comply with the Code’s principles or explain any deviations. The document highlights the importance of corporate social responsibility, whistleblowing policies, and succession planning as critical to effective governance. It seeks to guide companies towards improved sustainability, operational efficiency, and a stronger corporate culture aligned with international standards.', 'Egypt', 'climate', 'in_force', '2016-01-01'::date, 'Egypt', 'https://www.carrotsandsticks.org/policies/48_3', ARRAY['regulations', 'egypt', 'mandatory', 'sdg16', 'disclosure', 'sdg3']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('1109e8c4-4738-508e-8fc1-39bfb00ec586', 'Egypt’s Sustainable Development Strategy (Vision', 'Egypt’s Sustainable Development Strategy (Vision 2030)', 'The Sustainable Development Strategy (SDS): Egypt Vision 2030 outlines Egypt''s long-term strategy for inclusive, balanced, and sustainable development by 2030. The strategy is built upon three main pillars: economic, social, and environmental development. It emphasizes the need for a competitive, diversified economy, social justice, and environmental preservation. Vision 2030 seeks to address challenges such as inequality, poverty, and environmental degradation, with an emphasis on governance, transparency, and efficiency. The SDS includes detailed programs and projects across various sectors, such as education, health, energy, urban development, and culture, aiming to improve the quality of life for Egyptians while contributing to global sustainable development goals (SDGs). Key Performance Indicators (KPIs) have been established for each pillar to monitor progress, and a comprehensive framework for implementation and monitoring has been set up to ensure that objectives are met.', 'The Sustainable Development Strategy (SDS): Egypt Vision 2030 outlines Egypt''s long-term strategy for inclusive, balanced, and sustainable development by 2030. The strategy is built upon three main pillars: economic, social, and environmental development. It emphasizes the need for a competitive, diversified economy, social justice, and environmental preservation. Vision 2030 seeks to address challenges such as inequality, poverty, and environmental degradation, with an emphasis on governance, transparency, and efficiency. The SDS includes detailed programs and projects across various sectors, such as education, health, energy, urban development, and culture, aiming to improve the quality of life for Egyptians while contributing to global sustainable development goals (SDGs). Key Performance Indicators (KPIs) have been established for each pillar to monitor progress, and a comprehensive framework for implementation and monitoring has been set up to ensure that objectives are met.', 'The Sustainable Development Strategy (SDS): Egypt Vision 2030 outlines Egypt''s long-term strategy for inclusive, balanced, and sustainable development by 2030. The strategy is built upon three main pillars: economic, social, and environmental development. It emphasizes the need for a competitive, diversified economy, social justice, and environmental preservation. Vision 2030 seeks to address challenges such as inequality, poverty, and environmental degradation, with an emphasis on governance, transparency, and efficiency. The SDS includes detailed programs and projects across various sectors, such as education, health, energy, urban development, and culture, aiming to improve the quality of life for Egyptians while contributing to global sustainable development goals (SDGs). Key Performance Indicators (KPIs) have been established for each pillar to monitor progress, and a comprehensive framework for implementation and monitoring has been set up to ensure that objectives are met.', 'Egypt', 'climate', 'in_force', '2016-01-01'::date, 'Egypt', 'https://www.carrotsandsticks.org/policies/48_5', ARRAY['sdg4', 'sdg10', 'sdg7', 'egypt', 'mandatory', 'sdg16', 'mandatory_regulations', 'disclosure', 'sdg1', 'sdg3']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('317be776-a21a-50cf-b6fc-968e96363cb5', 'Egypt Guide to Corporate Governance Regulations and Standards', 'Guide to Corporate Governance Regulations and Standards in Egypt (March 2011)', 'The amended version of the Guide to Corporate Governance Regulations and Standards in Egypt issued in March 2011 was available in Arabic language only. Accordingly, this acted as a significant barrier to non-Arabic speaking researchers. The purpose of this document is to provide an unofficial translation of the Guide. The Guide includes an introduction, definitions, scope of implementation, discussion of apply or explain as the basis of implementation, and the regulations.', 'The amended version of the Guide to Corporate Governance Regulations and Standards in Egypt issued in March 2011 was available in Arabic language only. Accordingly, this acted as a significant barrier to non-Arabic speaking researchers. The purpose of this document is to provide an unofficial translation of the Guide. The Guide includes an introduction, definitions, scope of implementation, discussion of apply or explain as the basis of implementation, and the regulations.', 'The amended version of the Guide to Corporate Governance Regulations and Standards in Egypt issued in March 2011 was available in Arabic language only. Accordingly, this acted as a significant barrier to non-Arabic speaking researchers. The purpose of this document is to provide an unofficial translation of the Guide. The Guide includes an introduction, definitions, scope of implementation, discussion of apply or explain as the basis of implementation, and the regulations.', 'Egypt', 'nature', 'in_force', '2011-01-01'::date, 'Egypt', 'https://www.carrotsandsticks.org/policies/48_8', ARRAY['sdg14', 'regulations', 'egypt', 'sdg16', 'disclosure', 'voluntary']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('5d0a4600-61ce-54d7-8f9e-faa6662eaaea', 'Egypt Code of Corporate Governance for the Public Sector', 'Code of Corporate Governance for the Public Sector Enterprise, 2006', 'Corporate governance provisions for the public enterprise sector are complementary to the rules and provisions that govern these companies under existing laws and regulations. OECD’s “Guidelines on Corporate Governance for State Owned Enterprises (SOEs)” were taken as a reference point in preparing this Code of Corporate Governance for the Public Enterprise Sector in Egypt.', 'Corporate governance provisions for the public enterprise sector are complementary to the rules and provisions that govern these companies under existing laws and regulations. OECD’s “Guidelines on Corporate Governance for State Owned Enterprises (SOEs)” were taken as a reference point in preparing this Code of Corporate Governance for the Public Enterprise Sector in Egypt.', 'Corporate governance provisions for the public enterprise sector are complementary to the rules and provisions that govern these companies under existing laws and regulations. OECD’s “Guidelines on Corporate Governance for State Owned Enterprises (SOEs)” were taken as a reference point in preparing this Code of Corporate Governance for the Public Enterprise Sector in Egypt.', 'Egypt', 'governance', 'in_force', '2006-01-01'::date, 'Egypt', 'https://www.carrotsandsticks.org/policies/48_4', ARRAY['regulations', 'disclosure', 'mandatory', 'sdg16', 'egypt']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('7b60489a-8a9a-510e-922c-5c9b428d7950', 'El Salvador Sustainability Reporting Guidelines by the Superintendence of', 'Sustainability Reporting Guidelines by the Superintendence of the Securities and Insurance Market (SSM)', 'The Sustainability Reporting Guidelines (GRI Version 3.0) provide a comprehensive framework for organizations to report their economic, environmental, and social performance. The guidelines are designed to help businesses report transparently on their contributions to sustainable development, and to provide stakeholders with a reliable basis for decision-making. The guidelines include principles for defining report content and quality, guidance for boundary setting, and a standardized set of disclosures. These disclosures cover a range of topics including governance, environmental impact, labor practices, human rights, and product responsibility. The GRI framework emphasizes the importance of transparency, accountability, and stakeholder engagement in sustainability reporting. By following the GRI guidelines, organizations can report on their sustainability performance in a way that is balanced, clear, and consistent. The guidelines also stress the importance of including both positive and negative performance information and the need to provide a context for understanding the impact of the organization''s activities on society and the environment.', 'The Sustainability Reporting Guidelines (GRI Version 3.0) provide a comprehensive framework for organizations to report their economic, environmental, and social performance. The guidelines are designed to help businesses report transparently on their contributions to sustainable development, and to provide stakeholders with a reliable basis for decision-making. The guidelines include principles for defining report content and quality, guidance for boundary setting, and a standardized set of disclosures. These disclosures cover a range of topics including governance, environmental impact, labor practices, human rights, and product responsibility. The GRI framework emphasizes the importance of transparency, accountability, and stakeholder engagement in sustainability reporting. By following the GRI guidelines, organizations can report on their sustainability performance in a way that is balanced, clear, and consistent. The guidelines also stress the importance of including both positive and negative performance information and the need to provide a context for understanding the impact of the organization''s activities on society and the environment.', 'The Sustainability Reporting Guidelines (GRI Version 3.0) provide a comprehensive framework for organizations to report their economic, environmental, and social performance. The guidelines are designed to help businesses report transparently on their contributions to sustainable development, and to provide stakeholders with a reliable basis for decision-making. The guidelines include principles for defining report content and quality, guidance for boundary setting, and a standardized set of disclosures. These disclosures cover a range of topics including governance, environmental impact, labor practices, human rights, and product responsibility. The GRI framework emphasizes the importance of transparency, accountability, and stakeholder engagement in sustainability reporting. By following the GRI guidelines, organizations can report on their sustainability performance in a way that is balanced, clear, and consistent. The guidelines also stress the importance of including both positive and negative performance information and the need to provide a context for understanding the impact of the organization''s activities on society and the environment.', 'El Salvador', 'climate', 'in_force', '2020-01-01'::date, 'El Salvador', 'https://www.carrotsandsticks.org/policies/49_2', ARRAY['guidance_frameworks', 'other sustainability policy', 'sdg17', 'el salvador', 'sdg16', 'sdg9', 'voluntary']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('f83853e0-9c99-5c0f-942e-5263bbfee599', 'El Salvador Special Regulation of Technical Standards (Decree )', 'Special Regulation of Technical Standards (Decree No. 40)', 'The purpose of this Regulation is to determine the guidelines or directives for the establishment of technical standards of environmental quality in receiving environments, and the mechanisms for applying said standards, relative to the protection of the atmosphere, water , soil and bio-diversity.', 'The purpose of this Regulation is to determine the guidelines or directives for the establishment of technical standards of environmental quality in receiving environments, and the mechanisms for applying said standards, relative to the protection of the atmosphere, water , soil and bio-diversity.', 'The purpose of this Regulation is to determine the guidelines or directives for the establishment of technical standards of environmental quality in receiving environments, and the mechanisms for applying said standards, relative to the protection of the atmosphere, water , soil and bio-diversity.', 'El Salvador', 'climate', 'in_force', '2000-01-01'::date, 'El Salvador', 'https://www.carrotsandsticks.org/policies/49_11', ARRAY['sdg13', 'other sustainability policy', 'regulations', 'el salvador', 'mandatory', 'sdg6', 'sdg15']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('2a0e0ca7-5f27-51aa-9ec1-d45b853d5e7a', 'El Salvador Law against Money and Assets Laundering', 'Law against Money and Assets Laundering', 'This Law aims to prevent, detect, punish and eradicate crime of money and asset laundering, as well as its concealment.', 'This Law aims to prevent, detect, punish and eradicate crime of money and asset laundering, as well as its concealment.', 'This Law aims to prevent, detect, punish and eradicate crime of money and asset laundering, as well as its concealment.', 'El Salvador', 'climate', 'in_force', '1998-01-01'::date, 'El Salvador', 'https://www.carrotsandsticks.org/policies/49_1', ARRAY['other sustainability policy', 'regulations', 'el salvador', 'sdg11', 'mandatory', 'sdg15']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('41306055-6de3-52d8-868e-7ac6433bfede', 'El Salvador Environmental Law (Decree )', 'Environmental Law (Decree No. 233)', 'The purpose of this Law is to develop the Provisions of the Constitution of the Republic, which refer to the protection, conservation and recovery of the environment; the sustainable use of natural resources that allow improving the quality of life of present and future generations; as well as, regulate public and private environmental management and environmental protection as a basic obligation of the State, the Municipalities and the inhabitants in general; and ensure the application of the International Treaties or Agreements entered into by El Salvador in this matter.', 'The purpose of this Law is to develop the Provisions of the Constitution of the Republic, which refer to the protection, conservation and recovery of the environment; the sustainable use of natural resources that allow improving the quality of life of present and future generations; as well as, regulate public and private environmental management and environmental protection as a basic obligation of the State, the Municipalities and the inhabitants in general; and ensure the application of the International Treaties or Agreements entered into by El Salvador in this matter.', 'The purpose of this Law is to develop the Provisions of the Constitution of the Republic, which refer to the protection, conservation and recovery of the environment; the sustainable use of natural resources that allow improving the quality of life of present and future generations; as well as, regulate public and private environmental management and environmental protection as a basic obligation of the State, the Municipalities and the inhabitants in general; and ensure the application of the International Treaties or Agreements entered into by El Salvador in this matter.', 'El Salvador', 'climate', 'in_force', '1998-01-01'::date, 'El Salvador', 'https://www.carrotsandsticks.org/policies/49_4', ARRAY['sdg2', 'other sustainability policy', 'regulations', 'sdg7', 'el salvador', 'sdg11', 'mandatory', 'sdg12', 'sdg9']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('8b2c7ce8-64df-57ef-8f53-b985396bc585', 'El Salvador Law of Development and Territorial Ordering of', 'Law of Development and Territorial Ordering of the Area San Salvador Metropolitan and Municipalities (Decree No. 732)', 'The purpose of this Law is to regulate the land use planning and urban and rural development of the Metropolitan Area of San Salvador and Surrounding Municipalities, through the best use of the resources of the different areas and the full use of the instruments of planning.', 'The purpose of this Law is to regulate the land use planning and urban and rural development of the Metropolitan Area of San Salvador and Surrounding Municipalities, through the best use of the resources of the different areas and the full use of the instruments of planning.', 'The purpose of this Law is to regulate the land use planning and urban and rural development of the Metropolitan Area of San Salvador and Surrounding Municipalities, through the best use of the resources of the different areas and the full use of the instruments of planning.', 'El Salvador', 'climate', 'in_force', '1993-01-01'::date, 'El Salvador', 'https://www.carrotsandsticks.org/policies/49_9', ARRAY['other sustainability policy', 'regulations', 'el salvador', 'sdg11', 'mandatory', 'sdg15']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('995b8467-ba29-5dd1-9fd2-1da07a5205c0', 'Estonia Auditors Activities Act', 'Auditors Activities Act', 'This policy was published in 2025 by Estonia. It addresses sustainability and corporate responsibility requirements.', 'This policy was published in 2025 by Estonia. It addresses sustainability and corporate responsibility requirements.', 'This policy was published in 2025 by Estonia. It addresses sustainability and corporate responsibility requirements.', 'Estonia', 'climate', 'in_force', '2025-01-01'::date, 'Estonia', 'https://www.carrotsandsticks.org/policies/52_3', ARRAY['sdg13', 'regulations', 'mandatory', 'estonia', 'sdg16', 'sdg12']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('79737e27-b5f4-59a5-98c6-db9d3eb97c6e', 'Estonia Amendments to the Accounting Act and Amendments', 'Act on Amendments to the Accounting Act and Amendments to Other Acts', 'The Act on Amendments to the Accounting Act introduces changes to the accounting regulations in Estonia, effective from January 17, 2025. It mandates that certain businesses, particularly large enterprises and small and medium-sized enterprises (SMEs), must prepare sustainability reports alongside their annual reports, detailing environmental and social impacts. The law applies to all accounting entities, with specific criteria defining micro, small, medium, and large enterprises. Compliance with European Sustainability Reporting Standards (ESRS) is required, making this a mandatory reporting obligation for affected entities.', 'The Act on Amendments to the Accounting Act introduces changes to the accounting regulations in Estonia, effective from January 17, 2025. It mandates that certain businesses, particularly large enterprises and small and medium-sized enterprises (SMEs), must prepare sustainability reports alongside their annual reports, detailing environmental and social impacts. The law applies to all accounting entities, with specific criteria defining micro, small, medium, and large enterprises. Compliance with European Sustainability Reporting Standards (ESRS) is required, making this a mandatory reporting obligation for affected entities.', 'The Act on Amendments to the Accounting Act introduces changes to the accounting regulations in Estonia, effective from January 17, 2025. It mandates that certain businesses, particularly large enterprises and small and medium-sized enterprises (SMEs), must prepare sustainability reports alongside their annual reports, detailing environmental and social impacts. The law applies to all accounting entities, with specific criteria defining micro, small, medium, and large enterprises. Compliance with European Sustainability Reporting Standards (ESRS) is required, making this a mandatory reporting obligation for affected entities.', 'Estonia', 'climate', 'in_force', '2025-01-01'::date, 'Estonia', 'https://www.carrotsandsticks.org/policies/52_5', ARRAY['sdg13', 'regulations', 'mandatory', 'estonia', 'sdg16', 'sdg12', 'disclosure']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('bc09f454-9a60-527c-b66d-4dd604c5e3b1', 'Estonia Amendments to the Accounting Act', 'Act on Amendments to the Accounting Act 2025', 'The Act on Amendments to the Accounting Act 2025 updates specific provisions of the Accounting Act in Estonia, primarily extending deadlines for compliance from January 2026 to January 2028. It applies to all entities required to adhere to the Accounting Act. The amendments are mandatory and aim to align national regulations with European Union directives. This act is part of ongoing efforts to ensure accurate financial reporting and transparency within the Estonian accounting framework.', 'The Act on Amendments to the Accounting Act 2025 updates specific provisions of the Accounting Act in Estonia, primarily extending deadlines for compliance from January 2026 to January 2028. It applies to all entities required to adhere to the Accounting Act. The amendments are mandatory and aim to align national regulations with European Union directives. This act is part of ongoing efforts to ensure accurate financial reporting and transparency within the Estonian accounting framework.', 'The Act on Amendments to the Accounting Act 2025 updates specific provisions of the Accounting Act in Estonia, primarily extending deadlines for compliance from January 2026 to January 2028. It applies to all entities required to adhere to the Accounting Act. The amendments are mandatory and aim to align national regulations with European Union directives. This act is part of ongoing efforts to ensure accurate financial reporting and transparency within the Estonian accounting framework.', 'Estonia', 'climate', 'in_force', '2025-01-01'::date, 'Estonia', 'https://www.carrotsandsticks.org/policies/52_6', ARRAY['regulations', 'mandatory', 'estonia', 'sdg16', 'disclosure']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('be5ae4d9-6d09-5d0d-a5f6-ae73387dd92d', 'Estonia Act Amending the Accounting Act and Related Acts', 'Act Amending the Accounting Act and Related Acts', 'The purpose of this Act is to create the legal bases and establish general requirements for organising accounting and financial reporting pursuant to internationally recognised principles.', 'The purpose of this Act is to create the legal bases and establish general requirements for organising accounting and financial reporting pursuant to internationally recognised principles.', 'The purpose of this Act is to create the legal bases and establish general requirements for organising accounting and financial reporting pursuant to internationally recognised principles.', 'Estonia', 'climate', 'in_force', '2015-01-01'::date, 'Estonia', 'https://www.carrotsandsticks.org/policies/52_1', ARRAY['mandatory', 'other sustainability policy', 'estonia', 'regulations']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('d43b9d0e-37fa-5235-937b-9d1a8b406ef5', 'Estonia Corporate Governance Recommendations', 'Corporate Governance Recommendations 2006', 'The Corporate Governance Recommendations describe conduct, which contributes to better and more transparent of management and management control of companies. Additionally, the principles described in these Corporate Governance Recommendations are recommended to be carried out by Issuers and each Issuer shall decide whether or not they will adopt these principles as a basis for organizing their management.', 'The Corporate Governance Recommendations describe conduct, which contributes to better and more transparent of management and management control of companies. Additionally, the principles described in these Corporate Governance Recommendations are recommended to be carried out by Issuers and each Issuer shall decide whether or not they will adopt these principles as a basis for organizing their management.', 'The Corporate Governance Recommendations describe conduct, which contributes to better and more transparent of management and management control of companies. Additionally, the principles described in these Corporate Governance Recommendations are recommended to be carried out by Issuers and each Issuer shall decide whether or not they will adopt these principles as a basis for organizing their management.', 'Estonia', 'governance', 'in_force', '2006-01-01'::date, 'Estonia', 'https://www.carrotsandsticks.org/policies/52_2', ARRAY['guidance_frameworks', 'other sustainability policy', 'estonia', 'sdg16', 'voluntary']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('c3dcf611-f3cc-5abf-96b8-451c0ea220bc', 'Estonia Electricity Market Act', 'Electricity Market Act', 'The Electricity Market Act in Estonia, enacted in 2003, regulates electricity production, transmission, sale, export, and import. It aims to ensure affordable, environmentally compliant, efficient electricity supply, encouraging energy conservation. The policy applies to electricity market participants, emphasizing cooperation, transparency, and equal treatment.', 'The Electricity Market Act in Estonia, enacted in 2003, regulates electricity production, transmission, sale, export, and import. It aims to ensure affordable, environmentally compliant, efficient electricity supply, encouraging energy conservation. The policy applies to electricity market participants, emphasizing cooperation, transparency, and equal treatment.', 'The Electricity Market Act in Estonia, enacted in 2003, regulates electricity production, transmission, sale, export, and import. It aims to ensure affordable, environmentally compliant, efficient electricity supply, encouraging energy conservation. The policy applies to electricity market participants, emphasizing cooperation, transparency, and equal treatment.', 'Estonia', 'climate', 'in_force', '2003-01-01'::date, 'Estonia', 'https://www.carrotsandsticks.org/policies/52_4', ARRAY['regulations', 'sdg7', 'sdg17', 'mandatory', 'estonia', 'sdg16', 'sdg12']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('7a8d6200-525a-5ed4-a198-334db486b76c', 'Eswatini Stock Exchange ESG Reporting Guide', 'Eswatini Stock Exchange ESG Reporting Guide', 'The 2022 Eswatini Stock Exchange ESG Reporting Guide is a guide that sets out the Environmental, Social, and Governance (ESG) reporting requirements for companies listed on the Eswatini Stock Exchange. The guide provides a framework for companies to report on their ESG performance and impacts, including areas such as climate change, diversity and inclusion, human rights, and business ethics. The guide aims to promote transparency, accountability, and responsible business practices among listed companies in Eswatini. Companies are encouraged to use the guide to improve their ESG performance and provide investors with more comprehensive and comparable information to make informed investment decisions.', 'The 2022 Eswatini Stock Exchange ESG Reporting Guide is a guide that sets out the Environmental, Social, and Governance (ESG) reporting requirements for companies listed on the Eswatini Stock Exchange. The guide provides a framework for companies to report on their ESG performance and impacts, including areas such as climate change, diversity and inclusion, human rights, and business ethics. The guide aims to promote transparency, accountability, and responsible business practices among listed companies in Eswatini. Companies are encouraged to use the guide to improve their ESG performance and provide investors with more comprehensive and comparable information to make informed investment decisions.', 'The 2022 Eswatini Stock Exchange ESG Reporting Guide is a guide that sets out the Environmental, Social, and Governance (ESG) reporting requirements for companies listed on the Eswatini Stock Exchange. The guide provides a framework for companies to report on their ESG performance and impacts, including areas such as climate change, diversity and inclusion, human rights, and business ethics. The guide aims to promote transparency, accountability, and responsible business practices among listed companies in Eswatini. Companies are encouraged to use the guide to improve their ESG performance and provide investors with more comprehensive and comparable information to make informed investment decisions.', 'Eswatini', 'climate', 'in_force', '2022-01-01'::date, 'Eswatini', 'https://www.carrotsandsticks.org/policies/53_1', ARRAY['sdg13', 'sdg10', 'eswatini', 'sdg7', 'mandatory', 'sdg16', 'mandatory_regulations', 'disclosure', 'sdg9', 'sdg3']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('cfcc02fc-80d1-520a-97b2-2b968d39701f', 'Ethiopia Proclamation A Proclamation for Geothermal Resources Development', 'Proclamation No 981/2016 A Proclamation for Geothermal Resources Development', 'This Proclamation advances a legal and regulatory framework to support geothermal power generation by the public and private sectors, as part of electricity generation needs.', 'This Proclamation advances a legal and regulatory framework to support geothermal power generation by the public and private sectors, as part of electricity generation needs.', 'This Proclamation advances a legal and regulatory framework to support geothermal power generation by the public and private sectors, as part of electricity generation needs.', 'Ethiopia', 'climate', 'in_force', '2016-01-01'::date, 'Ethiopia', 'https://www.carrotsandsticks.org/policies/54_11', ARRAY['other sustainability policy', 'sdg7', 'mandatory', 'mandatory_regulations', 'ethiopia']::text[]) ON CONFLICT (id) DO NOTHING;
