INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('cc5d280d-2671-5be4-882f-9e91952cbb3d', 'Ethiopia Proclamation Commercial Registeration and Business Licensing Proclamation', 'Proclamation No 686/2010 Commercial Registeration and Business Licensing Proclamation', 'This Proclamation informs the objectives that include strengthening the situations where the trade sector can be supportive of the economic development of the country; protecting the trade sector from detrimental and unfair activities by appropriately organizing the systems of commercial registration and business licensing; facilitating the keeping of data regarding the trade sector by the government; creating conducive situations for commercial activities.', 'This Proclamation informs the objectives that include strengthening the situations where the trade sector can be supportive of the economic development of the country; protecting the trade sector from detrimental and unfair activities by appropriately organizing the systems of commercial registration and business licensing; facilitating the keeping of data regarding the trade sector by the government; creating conducive situations for commercial activities.', 'This Proclamation informs the objectives that include strengthening the situations where the trade sector can be supportive of the economic development of the country; protecting the trade sector from detrimental and unfair activities by appropriately organizing the systems of commercial registration and business licensing; facilitating the keeping of data regarding the trade sector by the government; creating conducive situations for commercial activities.', 'Ethiopia', 'climate', 'in_force', '2010-01-01'::date, 'Ethiopia', 'https://www.carrotsandsticks.org/policies/54_2', ARRAY['mandatory', 'other sustainability policy', 'ethiopia', 'regulations']::text[]) ON CONFLICT (id) DO NOTHING;
