INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('e477dbba-9bd6-5d88-a09f-22dd6d259ef5', 'Ethiopia Regulation Council of Ministers Regulation to Provide', 'Regulation No 159/2008 Council of Ministers Regulation to Provide for the Prevention of Industrial Pollution', 'Regulation of industrial production in the context of environmental standard, particularly the treatment of activities causing pollution.', 'Regulation of industrial production in the context of environmental standard, particularly the treatment of activities causing pollution.', 'Regulation of industrial production in the context of environmental standard, particularly the treatment of activities causing pollution.', 'Ethiopia', 'circularity', 'in_force', '2008-01-01'::date, 'Ethiopia', 'https://www.carrotsandsticks.org/policies/54_5', ARRAY['other sustainability policy', 'regulations', 'mandatory', 'sdg12', 'ethiopia']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('be2ed9bb-d717-5a3f-9ba0-85663304c6ac', 'Ethiopia Proclamation Labour Proclamation', 'Proclamation No 377 Labour Proclamation', 'This Proclamation revises the existing Labour law providing for the basic principles which govern worker-employer relations and for labour conditions taking into account the political, economic, and social policies of the Government and in conformity with the international conventions and other legal commitments to which Ethiopia is a party.', 'This Proclamation revises the existing Labour law providing for the basic principles which govern worker-employer relations and for labour conditions taking into account the political, economic, and social policies of the Government and in conformity with the international conventions and other legal commitments to which Ethiopia is a party.', 'This Proclamation revises the existing Labour law providing for the basic principles which govern worker-employer relations and for labour conditions taking into account the political, economic, and social policies of the Government and in conformity with the international conventions and other legal commitments to which Ethiopia is a party.', 'Ethiopia', 'social', 'in_force', '2004-01-01'::date, 'Ethiopia', 'https://www.carrotsandsticks.org/policies/54_10', ARRAY['sdg8', 'other sustainability policy', 'regulations', 'mandatory', 'ethiopia']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('23734ff9-e4ff-5b7c-aab4-a95e6da1ec0d', 'Ethiopia Proclamation Environmental Impact Assessment Proclamation', 'Proclamation No 299/2002 Environmental Impact Assessment Proclamation', 'This Proclamation informs how environmental impact assessment is defined, implemented and used in the territory of Ethiopia.', 'This Proclamation informs how environmental impact assessment is defined, implemented and used in the territory of Ethiopia.', 'This Proclamation informs how environmental impact assessment is defined, implemented and used in the territory of Ethiopia.', 'Ethiopia', 'climate', 'in_force', '2002-01-01'::date, 'Ethiopia', 'https://www.carrotsandsticks.org/policies/54_6', ARRAY['sdg2', 'other sustainability policy', 'regulations', 'sdg7', 'sdg11', 'mandatory', 'sdg12', 'sdg9', 'ethiopia']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('f9d6a231-e1e1-565f-b07d-933e9037c15a', 'Ethiopia Proclamation Animal Disease Prevention and Control Proclamation', 'Proclamation No 267/2002 Animal Disease Prevention and Control Proclamation', 'This Proclamation provides basis for a system to control the movement of animals, animal products and by-products within, into and out of the country.', 'This Proclamation provides basis for a system to control the movement of animals, animal products and by-products within, into and out of the country.', 'This Proclamation provides basis for a system to control the movement of animals, animal products and by-products within, into and out of the country.', 'Ethiopia', 'climate', 'in_force', '2002-01-01'::date, 'Ethiopia', 'https://www.carrotsandsticks.org/policies/54_8', ARRAY['sdg2', 'sdg14', 'other sustainability policy', 'mandatory', 'mandatory_regulations', 'sdg12', 'sdg9', 'sdg3', 'ethiopia']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('284c6121-df31-5af0-afbd-d7b9ada205c9', 'Ethiopia Proclamation A Proclamation to Promote the Development', 'Proclamation No 52/1993 A Proclamation to Promote the Development of Mineral Resources', 'This Proclamation creates the legal basis for the prospecting, exploration and exploitation of mineral resources for Ethiopia.', 'This Proclamation creates the legal basis for the prospecting, exploration and exploitation of mineral resources for Ethiopia.', 'This Proclamation creates the legal basis for the prospecting, exploration and exploitation of mineral resources for Ethiopia.', 'Ethiopia', 'climate', 'in_force', '1993-01-01'::date, 'Ethiopia', 'https://www.carrotsandsticks.org/policies/54_1', ARRAY['mandatory', 'other sustainability policy', 'mandatory_regulations', 'ethiopia']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('05bde08a-e670-537f-8d14-627a1c30626c', 'European Sustainability Reporting Standards (ESRS) under Commission Delegated', 'European Sustainability Reporting Standards (ESRS) under Commission Delegated Regulation (EU) 2023/2772.', 'The ESRS, developed under the Corporate Sustainability Reporting Directive (CSRD), provide detailed requirements for companies to disclose sustainability-related impacts, risks, and opportunities. The standards incorporate a double materiality approach, assessing both financial and environmental/social impacts of corporate activities. Covering cross-cutting, topical (Environmental, Social, and Governance), and sector-specific standards, ESRS ensure alignment with international frameworks like TCFD and the Paris Agreement. They include transitional provisions, such as phasing in reporting requirements, and focus on qualitative characteristics like comparability and verifiability. The ESRS are legally binding in all EU member states starting in 2024, aiming to enhance transparency, stakeholder trust, and regulatory coherence.', 'The ESRS, developed under the Corporate Sustainability Reporting Directive (CSRD), provide detailed requirements for companies to disclose sustainability-related impacts, risks, and opportunities. The standards incorporate a double materiality approach, assessing both financial and environmental/social impacts of corporate activities. Covering cross-cutting, topical (Environmental, Social, and Governance), and sector-specific standards, ESRS ensure alignment with international frameworks like TCFD and the Paris Agreement. They include transitional provisions, such as phasing in reporting requirements, and focus on qualitative characteristics like comparability and verifiability. The ESRS are legally binding in all EU member states starting in 2024, aiming to enhance transparency, stakeholder trust, and regulatory coherence.', 'The ESRS, developed under the Corporate Sustainability Reporting Directive (CSRD), provide detailed requirements for companies to disclose sustainability-related impacts, risks, and opportunities. The standards incorporate a double materiality approach, assessing both financial and environmental/social impacts of corporate activities. Covering cross-cutting, topical (Environmental, Social, and Governance), and sector-specific standards, ESRS ensure alignment with international frameworks like TCFD and the Paris Agreement. They include transitional provisions, such as phasing in reporting requirements, and focus on qualitative characteristics like comparability and verifiability. The ESRS are legally binding in all EU member states starting in 2024, aiming to enhance transparency, stakeholder trust, and regulatory coherence.', 'EU', 'climate', 'in_force', '2023-01-01'::date, 'European Commission', 'https://finance.ec.europa.eu/news/commission-adopts-european-sustainability-reporting-standards-2023-07-31_en', ARRAY['sdg13', 'regulations', 'sdg7', 'mandatory', 'sdg16', 'disclosure', 'eu']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('03aaa902-22a9-5368-993b-bf95773f63ce', 'COMMISSION DELEGATED REGULATION (EU) …/... of 31.7.2023 supplementing', 'COMMISSION DELEGATED REGULATION (EU) …/... of 31.7.2023 supplementing Directive 2013/34/EU of the European Parliament and of the Council as regards sustainability reporting standards', 'The Accounting Directive (2013/34/EU 1 ) as amended by the Corporate Sustainability Reporting Directive (CSRD - 2022/2464 2 ) requires large companies and listed small and medium-sized companies (SMEs), as well as parent companies of large groups, to include in a dedicated section of their management report the information necessary to understand the company’s impacts on sustainability matters, and the information necessary to understand how sustainability matters affect the company’s development, performance and position.', 'The Accounting Directive (2013/34/EU 1 ) as amended by the Corporate Sustainability Reporting Directive (CSRD - 2022/2464 2 ) requires large companies and listed small and medium-sized companies (SMEs), as well as parent companies of large groups, to include in a dedicated section of their management report the information necessary to understand the company’s impacts on sustainability matters, and the information necessary to understand how sustainability matters affect the company’s development, performance and position.', 'The Accounting Directive (2013/34/EU 1 ) as amended by the Corporate Sustainability Reporting Directive (CSRD - 2022/2464 2 ) requires large companies and listed small and medium-sized companies (SMEs), as well as parent companies of large groups, to include in a dedicated section of their management report the information necessary to understand the company’s impacts on sustainability matters, and the information necessary to understand how sustainability matters affect the company’s development, performance and position.', 'EU', 'climate', 'in_force', '2023-01-01'::date, 'European Union', 'https://www.carrotsandsticks.org/policies/308_34', ARRAY['sdg13', 'regulations', 'mandatory', 'sdg16', 'sdg12', 'disclosure', 'eu']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('c988271e-9084-5f0d-8efa-a46dc18edd41', 'Regulation (EU) of the European Parliament and', 'Regulation (EU) 2023/1115 of the European Parliament and of the Council of 31 May 2023 on the making available on the Union market and the export from the Union of certain commodities and products associated with deforestation and forest degradation and repealing Regulation (EU) No 995/2010', 'Europe''s 2023 deforestation law bans certain commodities linked to forest destruction within the EU and its exports. Timber, soy, beef, coffee, cocoa, and palm oil face scrutiny. Companies must prove responsible sourcing through due diligence efforts. This ambitious legislation aims to curb global deforestation, protect biodiversity, and promote sustainable trade practices within the EU market.', 'Europe''s 2023 deforestation law bans certain commodities linked to forest destruction within the EU and its exports. Timber, soy, beef, coffee, cocoa, and palm oil face scrutiny. Companies must prove responsible sourcing through due diligence efforts. This ambitious legislation aims to curb global deforestation, protect biodiversity, and promote sustainable trade practices within the EU market.', 'Europe''s 2023 deforestation law bans certain commodities linked to forest destruction within the EU and its exports. Timber, soy, beef, coffee, cocoa, and palm oil face scrutiny. Companies must prove responsible sourcing through due diligence efforts. This ambitious legislation aims to curb global deforestation, protect biodiversity, and promote sustainable trade practices within the EU market.', 'EU', 'climate', 'in_force', '2023-01-01'::date, 'European Union', 'https://eur-lex.europa.eu/eli/reg/2023/1115/oj', ARRAY['other sustainability policy', 'regulations', 'mandatory', 'sdg12', 'eu', 'sdg15']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('01499d49-6ae3-586a-b473-7be9acb529bc', 'EU Proposal for the Green Claims Directive', 'Proposal for the Green Claims Directive', 'The Green Claims Directive aims to combat greenwashing and ensure reliable, verifiable environmental claims for consumers. The directive introduces minimum criteria for substantiating voluntary environmental claims, requiring scientific evidence and life-cycle assessments for accuracy. It mandates transparency in labeling and substantiation, addressing misleading claims and unregulated ecolabels that confuse consumers. Designed to harmonize sustainability information across the EU, the proposal introduces third-party verification for claims and prohibits unverifiable or generic assertions. It also establishes governance standards for labeling schemes and restricts the creation of new regional or national ecolabels to reduce proliferation. By improving consumer trust and fostering a level playing field for businesses, the directive supports sustainable consumption and the EU''s transition to a green economy.', 'The Green Claims Directive aims to combat greenwashing and ensure reliable, verifiable environmental claims for consumers. The directive introduces minimum criteria for substantiating voluntary environmental claims, requiring scientific evidence and life-cycle assessments for accuracy. It mandates transparency in labeling and substantiation, addressing misleading claims and unregulated ecolabels that confuse consumers. Designed to harmonize sustainability information across the EU, the proposal introduces third-party verification for claims and prohibits unverifiable or generic assertions. It also establishes governance standards for labeling schemes and restricts the creation of new regional or national ecolabels to reduce proliferation. By improving consumer trust and fostering a level playing field for businesses, the directive supports sustainable consumption and the EU''s transition to a green economy.', 'The Green Claims Directive aims to combat greenwashing and ensure reliable, verifiable environmental claims for consumers. The directive introduces minimum criteria for substantiating voluntary environmental claims, requiring scientific evidence and life-cycle assessments for accuracy. It mandates transparency in labeling and substantiation, addressing misleading claims and unregulated ecolabels that confuse consumers. Designed to harmonize sustainability information across the EU, the proposal introduces third-party verification for claims and prohibits unverifiable or generic assertions. It also establishes governance standards for labeling schemes and restricts the creation of new regional or national ecolabels to reduce proliferation. By improving consumer trust and fostering a level playing field for businesses, the directive supports sustainable consumption and the EU''s transition to a green economy.', 'EU', 'climate', 'in_force', '2023-01-01'::date, 'European Parliament', 'https://www.europarl.europa.eu/RegData/etudes/BRIE/2023/753958/EPRS_BRI(2023)753958_EN.pdf', ARRAY['regulations', 'sdg7', 'mandatory', 'sdg16', 'sdg12', 'eu']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('5e732afd-3a1b-587f-badc-5eb81a36fcad', 'EU COM(2022) 453 - Proposal for a regulation', 'COM(2022) 453 - Proposal for a regulation on prohibiting products made with forced labour on the Union market', 'COM(2022) 453 is a proposal for a regulation by the European Commission to prohibit products made with forced labor from being sold in the European Union market. The proposed regulation aims to ensure that businesses operating in the EU do not contribute to human rights violations by preventing the importation and sale of goods that involve forced labor or other human rights abuses. The proposal outlines the obligations of businesses to conduct due diligence on their supply chains to ensure that they are free from forced labor, and it establishes penalties for non-compliance. The regulation also establishes a system for the EU to monitor and enforce the prohibition. The objective of the proposal is to promote respect for human rights and prevent forced labor from being used in the production of goods sold in the EU.', 'COM(2022) 453 is a proposal for a regulation by the European Commission to prohibit products made with forced labor from being sold in the European Union market. The proposed regulation aims to ensure that businesses operating in the EU do not contribute to human rights violations by preventing the importation and sale of goods that involve forced labor or other human rights abuses. The proposal outlines the obligations of businesses to conduct due diligence on their supply chains to ensure that they are free from forced labor, and it establishes penalties for non-compliance. The regulation also establishes a system for the EU to monitor and enforce the prohibition. The objective of the proposal is to promote respect for human rights and prevent forced labor from being used in the production of goods sold in the EU.', 'COM(2022) 453 is a proposal for a regulation by the European Commission to prohibit products made with forced labor from being sold in the European Union market. The proposed regulation aims to ensure that businesses operating in the EU do not contribute to human rights violations by preventing the importation and sale of goods that involve forced labor or other human rights abuses. The proposal outlines the obligations of businesses to conduct due diligence on their supply chains to ensure that they are free from forced labor, and it establishes penalties for non-compliance. The regulation also establishes a system for the EU to monitor and enforce the prohibition. The objective of the proposal is to promote respect for human rights and prevent forced labor from being used in the production of goods sold in the EU.', 'EU', 'climate', 'in_force', '2022-01-01'::date, 'European Commission', 'https://single-market-economy.ec.europa.eu/system/files/2022-09/COM-2022-453_en.pdf', ARRAY['sdg8', 'regulations', 'mandatory', 'sdg16', 'sdg12', 'disclosure', 'eu']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('c5922e1c-e1b0-5bc0-84c4-984eec685f38', 'Directive (EU) on Corporate Sustainability Reporting Directive (CSRD)', 'Directive (EU) 2022/2464 on Corporate Sustainability Reporting Directive (CSRD)', 'The CSRD revises and expands the EU’s non-financial reporting framework to enhance sustainability disclosures. It replaces the Non-Financial Reporting Directive (NFRD) and applies to a broader range of companies, including all large firms and listed small- and medium-sized enterprises (SMEs), excluding microenterprises. The directive mandates reporting on environmental, social, and governance (ESG) topics under a "double materiality" perspective, covering both the impact of sustainability matters on companies and their impact on people and the environment. It requires alignment with EU standards and frameworks like the Green Deal and Paris Agreement. The CSRD emphasizes comparability, reliability, and forward-looking disclosures, extending to companies operating outside the EU with significant EU activities. The European Financial Reporting Advisory Group (EFRAG) is tasked with developing the reporting standards.', 'The CSRD revises and expands the EU’s non-financial reporting framework to enhance sustainability disclosures. It replaces the Non-Financial Reporting Directive (NFRD) and applies to a broader range of companies, including all large firms and listed small- and medium-sized enterprises (SMEs), excluding microenterprises. The directive mandates reporting on environmental, social, and governance (ESG) topics under a "double materiality" perspective, covering both the impact of sustainability matters on companies and their impact on people and the environment. It requires alignment with EU standards and frameworks like the Green Deal and Paris Agreement. The CSRD emphasizes comparability, reliability, and forward-looking disclosures, extending to companies operating outside the EU with significant EU activities. The European Financial Reporting Advisory Group (EFRAG) is tasked with developing the reporting standards.', 'The CSRD revises and expands the EU’s non-financial reporting framework to enhance sustainability disclosures. It replaces the Non-Financial Reporting Directive (NFRD) and applies to a broader range of companies, including all large firms and listed small- and medium-sized enterprises (SMEs), excluding microenterprises. The directive mandates reporting on environmental, social, and governance (ESG) topics under a "double materiality" perspective, covering both the impact of sustainability matters on companies and their impact on people and the environment. It requires alignment with EU standards and frameworks like the Green Deal and Paris Agreement. The CSRD emphasizes comparability, reliability, and forward-looking disclosures, extending to companies operating outside the EU with significant EU activities. The European Financial Reporting Advisory Group (EFRAG) is tasked with developing the reporting standards.', 'EU', 'climate', 'in_force', '2022-01-01'::date, 'Climate Laws', 'https://climate-laws.org/document/directive-eu-2022-2464-of-the-european-parliament-and-of-the-council-of-14-december-2022-amending-regulation-eu-no-537-2014-directive-2004-109-ec-directive-2006-43-ec-and-directive-2013-34-eu-as-regards-corporate-sustainability-reporting-corporate-sustainability-reporting-directive_3a34', ARRAY['sdg13', 'regulations', 'sdg7', 'mandatory', 'sdg16', 'eu']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('e990f25b-6673-5749-bf1a-4236a2d2341d', 'Proposal for a Regulation of the European Parliament', 'Proposal for a Regulation of the European Parliament and of the Council on the making available on the Union market as well as export from the Union of certain commodities and products associated with deforestation and forest degradation and repealing Regulation (EU) No 995/2010', 'The Proposal for a Regulation of the European Parliament and of the Council aims to prevent the importation and exportation of commodities and products associated with deforestation and forest degradation in the European Union. The proposed regulation would require companies to conduct due diligence on their supply chains and ensure that the products they import or export do not contribute to deforestation or forest degradation. The proposed regulation repeals Regulation (EU) No 995/2010 and establishes new provisions, such as the requirement to obtain a license for the import or export of certain products, including soy, palm oil, and beef. The proposed regulation also aims to promote sustainable land use practices and establish a level playing field for companies operating in the EU market. The objective of the proposal is to reduce the EU''s contribution to global deforestation and promote responsible production and consumption practices.', 'The Proposal for a Regulation of the European Parliament and of the Council aims to prevent the importation and exportation of commodities and products associated with deforestation and forest degradation in the European Union. The proposed regulation would require companies to conduct due diligence on their supply chains and ensure that the products they import or export do not contribute to deforestation or forest degradation. The proposed regulation repeals Regulation (EU) No 995/2010 and establishes new provisions, such as the requirement to obtain a license for the import or export of certain products, including soy, palm oil, and beef. The proposed regulation also aims to promote sustainable land use practices and establish a level playing field for companies operating in the EU market. The objective of the proposal is to reduce the EU''s contribution to global deforestation and promote responsible production and consumption practices.', 'The Proposal for a Regulation of the European Parliament and of the Council aims to prevent the importation and exportation of commodities and products associated with deforestation and forest degradation in the European Union. The proposed regulation would require companies to conduct due diligence on their supply chains and ensure that the products they import or export do not contribute to deforestation or forest degradation. The proposed regulation repeals Regulation (EU) No 995/2010 and establishes new provisions, such as the requirement to obtain a license for the import or export of certain products, including soy, palm oil, and beef. The proposed regulation also aims to promote sustainable land use practices and establish a level playing field for companies operating in the EU market. The objective of the proposal is to reduce the EU''s contribution to global deforestation and promote responsible production and consumption practices.', 'EU', 'climate', 'in_force', '2021-01-01'::date, 'European Commission', 'https://environment.ec.europa.eu/document/download/15e6d00c-28bc-48db-9b32-b485742d372b_en?filename=Proposal+for+a+Regulation+-+EUDR.pdf', ARRAY['regulations', 'mandatory', 'sdg12', 'disclosure', 'eu', 'sdg15']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('a42bb9bd-85f9-5bb0-9899-fe25df01111a', 'Regulation (EU) – The European Climate Law', 'Regulation (EU) 2021/1119 – The European Climate Law', 'The European Climate Law (Regulation (EU) 2021/1119) establishes a legal framework for achieving climate neutrality in the EU by 2050. It sets binding targets for reducing greenhouse gas (GHG) emissions and integrates climate goals into all EU policies. The law aims to ensure predictability, accountability, and transparency in climate action, aligning the EU with the Paris Agreement and the European Green Deal.

Key provisions include:

Climate Neutrality Target:
The EU must achieve net-zero GHG emissions by 2050 and aim for negative emissions thereafter.
Binding 2030 Climate Target:
GHG emissions must be reduced by at least 55% compared to 1990 levels by 2030.
The contribution of carbon removals to the 2030 target is capped at 225 million tonnes of CO₂ equivalent.
Intermediate 2040 Target:
The Commission must propose a 2040 climate target after the first global stocktake under the Paris Agreement.
A projected EU greenhouse gas budget for 2030–2050 will be published.
Sectoral Climate Action & Just Transition:
All economic sectors, including energy, industry, transport, and agriculture, must contribute to net-zero emissions.
A Just Transition Mechanism supports regions and workers affected by the green transition.
Climate Adaptation Strategy:
Member States must adopt national adaptation plans to strengthen resilience to climate change impacts.
Governance & Progress Monitoring:
The European Scientific Advisory Board on Climate Change provides independent scientific advice.
The Commission must assess progress every five years and issue recommendations if national measures are inconsistent with EU climate goals.
Climate Finance & Carbon Pricing:
EU budget and recovery funds must allocate at least 30% of spending to climate objectives.
The Carbon Border Adjustment Mechanism (CBAM) will prevent carbon leakage.
The European Climate Law legally binds the EU to climate neutrality, ensuring a structured, science-based approach to emissions reductions and adaptation strategies.', 'The European Climate Law (Regulation (EU) 2021/1119) establishes a legal framework for achieving climate neutrality in the EU by 2050. It sets binding targets for reducing greenhouse gas (GHG) emissions and integrates climate goals into all EU policies. The law aims to ensure predictability, accountability, and transparency in climate action, aligning the EU with the Paris Agreement and the European Green Deal.

