INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('4cb62243-1efb-55e7-a3ef-acc38f0e874d', 'Commission Delegated Directive (EU) .../… of 21.4.2021 amending', 'Commission Delegated Directive (EU) .../… of 21.4.2021 amending Delegated Directive (EU) 2017/593 as regards the integration of sustainability factors into the product governance obligations', 'This Directive and other sectoral delegated acts that adapt rules on fiduciary duties and that were adopted alongside also reinforce Regulation (EU) 2019/2088 of the European Parliament and of the Council7, Regulation (EU) 2019/2089 of the European Parliament and of the Council8 and Regulation (EU) 2020/852 of the European Parliament and of the Council. Those rules integrate sustainability considerations into the investment, advisory and disclosure processes in a consistent manner across sectors. They anchor environmental, social and governance (sustainability) considerations at the heart of the financial system to help transform Europe''s economy into a greener, low-carbon, more resilient, resource- efficient and circular system.', 'This Directive and other sectoral delegated acts that adapt rules on fiduciary duties and that were adopted alongside also reinforce Regulation (EU) 2019/2088 of the European Parliament and of the Council7, Regulation (EU) 2019/2089 of the European Parliament and of the Council8 and Regulation (EU) 2020/852 of the European Parliament and of the Council. Those rules integrate sustainability considerations into the investment, advisory and disclosure processes in a consistent manner across sectors. They anchor environmental, social and governance (sustainability) considerations at the heart of the financial system to help transform Europe''s economy into a greener, low-carbon, more resilient, resource- efficient and circular system.', 'This Directive and other sectoral delegated acts that adapt rules on fiduciary duties and that were adopted alongside also reinforce Regulation (EU) 2019/2088 of the European Parliament and of the Council7, Regulation (EU) 2019/2089 of the European Parliament and of the Council8 and Regulation (EU) 2020/852 of the European Parliament and of the Council. Those rules integrate sustainability considerations into the investment, advisory and disclosure processes in a consistent manner across sectors. They anchor environmental, social and governance (sustainability) considerations at the heart of the financial system to help transform Europe''s economy into a greener, low-carbon, more resilient, resource- efficient and circular system.', 'EU', 'climate', 'in_force', '2021-01-01'::date, 'EUR-Lex / Strada lex', 'https://www.stradalex.eu/en/se_src_publ_leg_eur_jo/document/ojeu_2021.277.01.0137.01', ARRAY['sdg13', 'other sustainability policy', 'regulations', 'mandatory', 'sdg16', 'eu']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('bc4585ca-5a8b-5f3e-8409-40efcfc2dfcd', 'EU Commission Delegated Regulation on sustainability factors, risks', 'EU Commission Delegated Regulation on sustainability factors, risks, and preferences in product oversight and governance requirements for insurance undertakings and insurance distributors', 'This Regulation is part of a broader Commission''s initiative on sustainable development. It lays the foundation for an EU framework which puts sustainability considerations at the heart of the financial system to support transforming Europe''s economy into a greener, more resilient and circular system in line with the European Green Deal objectives.', 'This Regulation is part of a broader Commission''s initiative on sustainable development. It lays the foundation for an EU framework which puts sustainability considerations at the heart of the financial system to support transforming Europe''s economy into a greener, more resilient and circular system in line with the European Green Deal objectives.', 'This Regulation is part of a broader Commission''s initiative on sustainable development. It lays the foundation for an EU framework which puts sustainability considerations at the heart of the financial system to support transforming Europe''s economy into a greener, more resilient and circular system in line with the European Green Deal objectives.', 'EU', 'climate', 'in_force', '2021-01-01'::date, 'NBS (National Bank of Slovakia)', 'https://nbs.sk/en/dohlad-nad-financnym-trhom/legislativa/legislativa/detail-dokumentu/commission-delegated-regulation-eu-2021-1257-of-21-april-2021-amending-delegated-regulations-eu-2017-2358-and-eu-2017-2359-as-regards-the-integration-of-sustainability-factors-risks-and-prefere/', ARRAY['other sustainability policy', 'regulations', 'mandatory', 'sdg16', 'eu']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('773c8933-59f1-5f99-aab1-a910205df35e', 'Commission Delegated Regulation (EU) .../... of 21.4.2021 amending', 'Commission Delegated Regulation (EU) .../... of 21.4.2021 amending Delegated Regulation (EU) No 231/2013 as regards the sustainability risks and sustainability factors to be taken into account by Alternative Investment Fund Managers', 'This Regulation clarifies the current obligation of AIFMs to integrate sustainability risks and also clarifies some of implications of Regulation on sustainability-related disclosures in the financial services sector, namely where AIFMs disclose information with regard to the consideration of adverse sustainability impacts.', 'This Regulation clarifies the current obligation of AIFMs to integrate sustainability risks and also clarifies some of implications of Regulation on sustainability-related disclosures in the financial services sector, namely where AIFMs disclose information with regard to the consideration of adverse sustainability impacts.', 'This Regulation clarifies the current obligation of AIFMs to integrate sustainability risks and also clarifies some of implications of Regulation on sustainability-related disclosures in the financial services sector, namely where AIFMs disclose information with regard to the consideration of adverse sustainability impacts.', 'EU', 'climate', 'in_force', '2021-01-01'::date, 'European Commission', 'https://www.carrotsandsticks.org/policies/308_7', ARRAY['sdg13', 'other sustainability policy', 'regulations', 'mandatory', 'sdg16', 'sdg12', 'eu']::text[]) ON CONFLICT (id) DO NOTHING;
