INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('774e7881-8de3-5e2b-9b86-bca5e6884a0c', 'Commission Delegated Regulation (EU) .../... of 21.4.2021 amending', 'Commission Delegated Regulation (EU) .../... of 21.4.2021 amending Delegated Regulation (EU) 2015/35 as regards the integration of sustainability risks in the governance of insurance and reinsurance undertakings', 'This Regulation and other sectoral delegated acts that adapt rules on fiduciary duties and suitability tests further reinforce the Regulation on sustainability-related disclosures in the financial services sector, the Regulation on the EU Climate Transition Benchmarks, EU Paris-aligned Benchmarks and sustainability-related disclosures for benchmarks5 and the Regulation on the EU taxonomy for sustainable activities.', 'This Regulation and other sectoral delegated acts that adapt rules on fiduciary duties and suitability tests further reinforce the Regulation on sustainability-related disclosures in the financial services sector, the Regulation on the EU Climate Transition Benchmarks, EU Paris-aligned Benchmarks and sustainability-related disclosures for benchmarks5 and the Regulation on the EU taxonomy for sustainable activities.', 'This Regulation and other sectoral delegated acts that adapt rules on fiduciary duties and suitability tests further reinforce the Regulation on sustainability-related disclosures in the financial services sector, the Regulation on the EU Climate Transition Benchmarks, EU Paris-aligned Benchmarks and sustainability-related disclosures for benchmarks5 and the Regulation on the EU taxonomy for sustainable activities.', 'EU', 'climate', 'in_force', '2021-01-01'::date, 'Malta Financial Services Authority', 'https://www.mfsa.mt/wp-content/uploads/2022/06/Circular-on-Commission-Delegated-Regulation-EU-2021-1256-amending-Delegated-Regulation-EU-2015-35.pdf',